import java.io.*;
import java.util.*;

public class Main {
    static long amount(String s) {
        return s.matches("[1-9]\\d{0,8}") ? Long.parseLong(s) : -1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        Bank bank = new Bank();
        for (String raw; (raw = in.readLine()) != null; ) {
            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            String reply;
            if (p[0].equals("OPEN") && p.length == 3) reply = bank.open(p[1], p[2]);
            else if ((p[0].equals("DEPOSIT") || p[0].equals("WITHDRAW")) && p.length == 3) {
                Account a = bank.find(p[1]);
                long amt = amount(p[2]);
                if (a == null) reply = "error: no account " + p[1];
                else if (amt < 0) reply = "error: bad amount " + p[2];
                else if (p[0].equals("DEPOSIT")) { a.deposit(amt); reply = a.id + " balance " + a.balance(); }
                else reply = a.withdraw(amt) ? a.id + " balance " + a.balance() : "error: insufficient funds in " + a.id;
            } else if (p[0].equals("TRANSFER") && p.length == 4) {
                long amt = amount(p[3]);
                reply = amt < 0 ? "error: bad amount " + p[3] : bank.transfer(p[1], p[2], amt);
            } else if (p[0].equals("STATEMENT") && p.length == 2) {
                Account a = bank.find(p[1]);
                if (a == null) reply = "error: no account " + p[1];
                else {
                    List<String> lines = a.statement();
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < lines.size(); i++) sb.append(i > 0 ? "\n" : "").append(i + 1).append(". ").append(lines.get(i));
                    reply = lines.isEmpty() ? "no transactions" : sb.toString();
                }
            } else reply = "error: bad command " + raw.trim();
            out.append(reply).append('\n');
        }
        System.out.print(out);
    }
}

