import java.util.*;

class Account {
    final String id;
    final String owner;
    private long balance;
    private final List<String> history = new ArrayList<>();

    Account(String id, String owner) {
        this.id = id;
        this.owner = owner;
    }

    long balance() { return balance; }

    void deposit(long amount) {
        balance += amount;
        history.add("deposit " + amount + " -> " + balance);
    }

    boolean withdraw(long amount) {
        if (amount > balance) return false;
        balance -= amount;
        history.add("withdraw " + amount + " -> " + balance);
        return true;
    }

    void note(String line) {
        history.add(line + " -> " + balance);
    }

    List<String> statement() { return List.copyOf(history); }
}

import java.util.*;

class Bank {
    private final Map<String, Account> accounts = new HashMap<>();

    String open(String id, String owner) {
        if (accounts.containsKey(id)) return "error: account " + id + " exists";
        accounts.put(id, new Account(id, owner));
        return "opened " + id + " for " + owner;
    }

    Account find(String id) { return accounts.get(id); }

    String transfer(String from, String to, long amount) {
        Account a = accounts.get(from), b = accounts.get(to);
        if (a == null) return "error: no account " + from;
        if (b == null) return "error: no account " + to;
        if (a == b) return "error: same account";
        if (amount > a.balance()) return "error: insufficient funds in " + from;
        a.withdraw(amount);
        b.deposit(amount);
        return "moved " + amount + " from " + from + " to " + to;
    }
}
